// The value this whole assignment is about: one reading from a small sensor
// node. Every part takes this same struct to bytes and back, a different way.
//
// DO NOT EDIT this file — the tests and the golden files in data/ depend on it.

#ifndef AIS2203_SENSOR_DATA_HPP
#define AIS2203_SENSOR_DATA_HPP

#include <cstdint>
#include <optional>
#include <string>

namespace ais2203 {

struct SensorData {
    struct IMU {
        bool is_valid{false};
        double roll{0};
        double pitch{0};
        double yaw{0};

        bool operator==(const IMU&) const = default;   // C++20: member-wise ==
    };

    struct Accelerometer {
        bool is_valid{false};
        double x{0};
        double y{0};
        double z{0};

        bool operator==(const Accelerometer&) const = default;
    };

    std::string sensor_id;            // e.g. "imu-north-01"
    std::uint32_t sequence{0};        // counts up by one per reading
    std::int64_t timestamp_ms{0};     // milliseconds since the Unix epoch
    IMU imu;
    Accelerometer accelerometer;
    std::optional<double> temperature;   // not every node has the sensor

    bool operator==(const SensorData&) const = default;
};

} // namespace ais2203

#endif // AIS2203_SENSOR_DATA_HPP
